using Engine;
using Game;
using Game.Westworld;
using System.Text.Json;
using Westworld.Runtime.Core;
using Westworld.Scapi.Adapter;
// Native integration positive control, not model autonomy or natural hunting.
internal sealed class CookingScenario:IUpdateable,IDisposable {
 public float FloatUpdateOrder=>-14;public bool Done{get;private set;}
 readonly ComponentPlayer p;readonly AtomicActions actions;readonly ActorTools tools;readonly SubsystemTerrain terrain;
 readonly NativeActorSession senses;readonly ScapiInterestBackend backend;readonly InterestCoordinator interests;
 readonly Point3 table,resource,furnaceCell;readonly Vector3 origin;readonly Dictionary<int,int> baseline;
 AtomicActionRun run;ComponentFurnace furnace;int stage,harvested,expected;double elapsed,started;float foodBefore;long eatenBefore;bool disposed;
 IInventory Inventory=>p.ComponentMiner.Inventory;
 public CookingScenario(ComponentPlayer player,Point3 workbench,AtomicActions sharedActions,ActorTools sharedTools){p=player;table=workbench;origin=p.ComponentBody.Position;terrain=p.Project.FindSubsystem<SubsystemTerrain>(true);
  resource=new(Terrain.ToCell(origin.X)-2,Terrain.ToCell(origin.Y),Terrain.ToCell(origin.Z));furnaceCell=new(table.X,table.Y,table.Z+1);
  baseline=Enumerable.Range(0,Inventory.SlotsCount).Where(i=>Inventory.GetSlotCount(i)>0).GroupBy(Inventory.GetSlotValue).ToDictionary(g=>g.Key,g=>g.Sum(Inventory.GetSlotCount));
  Require(new[]{OakWoodBlock.Index,PlanksBlock.Index,CobblestoneBlock.Index,FurnaceBlock.Index,RawMeatBlock.Index,CookedMeatBlock.Index}.All(c=>Count(c)==0),"production materials already present");
  senses=new NativeActorSession(p.Project,Guid.NewGuid(),actionsEnabled:false);senses.Bind(Guid.NewGuid(),p);p.Project.FindSubsystem<SubsystemUpdate>(true).AddUpdateable(senses);backend=new(terrain,p.Project.FindSubsystem<SubsystemSpawn>(true));interests=new(senses.Registry,backend,new InterestRadii(16,32));interests.Sync();terrain.TerrainUpdater.RemoveUpdateLocation(p.PlayerData.PlayerIndex);
  actions=sharedActions;tools=sharedTools;int emptyHand=Enumerable.Range(0,Inventory.SlotsCount).First(i=>Inventory.GetSlotCount(i)==0);var select=actions.Start(new SelectItem(emptyHand,Inventory.GetSlotValue(emptyHand)));Require(select.Result.Status==AtomicActionStatus.Succeeded,"cannot select empty hand for resource collection");Log("cooking_fixture_started",new{resource=new[]{resource.X,resource.Y,resource.Z},table=new[]{table.X,table.Y,table.Z},baseline=Slots(Inventory),stagedWorldResources="one oak log then eight granite blocks at same cell",rawMeat="one artificial world pickable after native harvesting, NOT hunting"});SpawnResource();
 }
 static void Require(bool v,string reason){if(!v)throw new InvalidOperationException(reason);}
 void Log(string kind,object data)=>CookingGate.Log(new{kind,data});
 object Slots(IInventory inv)=>Enumerable.Range(0,inv.SlotsCount).Select(i=>new{slot=i,value=inv.GetSlotValue(i),count=inv.GetSlotCount(i)}).ToArray();
 int Count(int c)=>Enumerable.Range(0,Inventory.SlotsCount).Where(i=>Terrain.ExtractContents(Inventory.GetSlotValue(i))==c).Sum(Inventory.GetSlotCount);
 int Slot(int c)=>Enumerable.Range(0,Inventory.SlotsCount).First(i=>Inventory.GetSlotCount(i)>0&&Terrain.ExtractContents(Inventory.GetSlotValue(i))==c);
 JsonElement Call(string name,object args=null){using var j=JsonDocument.Parse(tools.InvokeJson(name,JsonSerializer.Serialize(args??new{})));Require(j.RootElement.GetProperty("ok").GetBoolean(),name+": "+j.RootElement);return j.RootElement.GetProperty("data").Clone();}
 JsonElement Observe()=>Call("observe",new{look_distance=5,object_distance=5,limit=24});
 bool TaskDone(){var t=Call("task_status");string s=t.GetProperty("status").GetString();if(s is "waiting" or "running")return false;Require(s=="succeeded","native task failed: "+t);Log("task_completed",t);return true;}
 bool ActionDone(){if(run.Result.Status==AtomicActionStatus.Running)return false;Require(run.Result.Status==AtomicActionStatus.Succeeded,"native action failed: "+run.Result);return true;}
 void Aim(Point3 cell,int next){run=actions.Start(new FaceTowards(new Vector3(cell.X+.5f,cell.Y+.5f,cell.Z+.5f)));stage=next;}
 void SpawnResource(){Require(Terrain.ExtractContents(terrain.Terrain.GetCellValue(resource.X,resource.Y,resource.Z))==0,"resource fixture cell not empty");expected=harvested==0?OakWoodBlock.Index:CobblestoneBlock.Index;terrain.ChangeCell(resource.X,resource.Y,resource.Z,harvested==0?OakWoodBlock.Index:GraniteBlock.Index);Log("artificial_resource_placed",new{ordinal=harvested,content=harvested==0?OakWoodBlock.Index:GraniteBlock.Index});Aim(resource,1);}
 void Craft(int value,int count,bool external){var o=Observe();var recipes=Call("find_recipes",new{result_value=value,offset=0,limit=32});Require(recipes.GetArrayLength()>0,"no recipe");var recipe=recipes.EnumerateArray().First(r=>r.GetProperty("recipe").GetProperty("resultValue").GetInt32()==value);Call("plan_craft",new{workspace=external?o.GetProperty("focus").GetProperty("storageReference").GetString():o.GetProperty("craftingReference").GetString(),recipe=recipe.GetProperty("reference").GetString(),count});Log("craft_started",new{value,count,recipe});}
 void Transfer(IInventory source,int sourceSlot,IInventory destination,int destinationSlot){run=actions.Start(new TransferItems(new(source,sourceSlot,source.GetSlotValue(sourceSlot)),new(destination,destinationSlot,destination.GetSlotValue(destinationSlot)),1));}
 public void Update(float dt){elapsed+=dt;interests.Sync();Require(elapsed<350&&p.ComponentHealth.Health>0&&p.GameWidget is null,"cooking timeout or actor unavailable");
  if(stage==1&&ActionDone()){var o=Observe();Require(actions.Queries.LookAhead(5)?.Cell==resource,"resource not eye-visible");Call("submit_plan",new{steps=new object[]{new{tool="act_Dig",arguments=new{target=o.GetProperty("focus").GetProperty("reference").GetString(),timeout=30},minimum_affected=1}}});stage=2;}
  else if(stage==2&&TaskDone()){run=actions.Start(new MoveTo(new Vector3(resource.X+1.2f,resource.Y,resource.Z+.5f),.3f,6));stage=3;}
  else if(stage==3&&run.Result.Status!=AtomicActionStatus.Running){if(Count(expected)!=(harvested==0?1:harvested))return;harvested++;Log("native_resource_picked",new{harvested,inventory=Slots(Inventory),approach=run.Result.Status.ToString()});run=actions.Start(new MoveTo(origin,.3f,8));stage=4;}
  else if(stage==4&&ActionDone()){if(harvested<9)SpawnResource();else{Require(Count(OakWoodBlock.Index)==1&&Count(CobblestoneBlock.Index)==8,"harvest accounting");Craft(PlanksBlock.Index,4,false);stage=5;}}
  else if(stage==5&&TaskDone()){Require(Count(OakWoodBlock.Index)==0&&Count(PlanksBlock.Index)==4,"fuel production accounting");Aim(table,6);}
  else if(stage==6&&ActionDone()){Require(actions.Queries.LookAhead(5)?.Cell==table,"earned table not visible");Craft(FurnaceBlock.Index,1,true);stage=7;}
  else if(stage==7&&TaskDone()){Require(Count(CobblestoneBlock.Index)==0&&Count(FurnaceBlock.Index)==1,"furnace recipe accounting");run=actions.Start(new FaceTowards(new Vector3(furnaceCell.X+.5f,furnaceCell.Y-.01f,furnaceCell.Z+.5f)));stage=8;}
  else if(stage==8&&ActionDone()){var o=Observe();Require(actions.Queries.LookAhead(5)?.Cell==new Point3(furnaceCell.X,furnaceCell.Y-1,furnaceCell.Z),"furnace support not visible");int slot=Slot(FurnaceBlock.Index);Call("act_Place",new{target=o.GetProperty("focus").GetProperty("reference").GetString(),slot,value=Inventory.GetSlotValue(slot)});stage=9;}
  else if(stage==9){var a=Call("action_status");if(a.GetProperty("status").GetString()=="running")return;Require(a.GetProperty("status").GetString()=="succeeded"&&Count(FurnaceBlock.Index)==0,"furnace placement failed");furnace=p.Project.FindSubsystem<SubsystemBlockEntities>(true).GetBlockEntity(furnaceCell)?.Entity.FindComponent<ComponentFurnace>(true);Require(furnace is not null,"furnace entity missing");p.Project.FindSubsystem<SubsystemPickables>(true).AddPickable(RawMeatBlock.Index,1,origin+new Vector3(0,.2f,0),Vector3.Zero,null);Log("artificial_raw_meat_world_drop",new{count=1,inventoryInjection=false});stage=10;}
  else if(stage==10){if(Count(RawMeatBlock.Index)!=1)return;Aim(furnaceCell,11);}
  else if(stage==11&&ActionDone()){Observe();Require(actions.Queries.LookAhead(5)?.Cell==furnaceCell,"furnace not visible");Require(furnace.GetSlotCapacity(furnace.FuelSlotIndex,RawMeatBlock.Index)==0,"invalid fuel accepted by native capacity");Transfer(Inventory,Slot(RawMeatBlock.Index),furnace,0);stage=12;}
  else if(stage==12&&ActionDone()){started=elapsed;stage=13;}
  else if(stage==13&&elapsed-started>=1){Require(furnace.GetSlotCount(0)==1&&furnace.GetSlotCount(furnace.ResultSlotIndex)==0&&furnace.HeatLevel==0,"unfueled furnace created product");Log("unfueled_and_invalid_fuel_verified",new{slots=Slots(furnace)});var cancelled=actions.Start(new Wait(5));Require(actions.Cancel(cancelled)&&cancelled.Result.Status==AtomicActionStatus.Cancelled,"bounded wait cancellation failed");Require(furnace.GetSlotCount(0)==1&&furnace.GetSlotCount(furnace.ResultSlotIndex)==0,"cancel mutated stored materials");Log("wait_cancelled_without_rollback",new{status=cancelled.Result.Status.ToString(),slots=Slots(furnace)});Transfer(Inventory,Slot(PlanksBlock.Index),furnace,furnace.FuelSlotIndex);stage=14;}
  else if(stage==14&&ActionDone()){started=elapsed;stage=15;}
  else if(stage==15){Require(elapsed-started<15,"cooking did not complete");if(furnace.GetSlotCount(furnace.ResultSlotIndex)!=1)return;Require(Terrain.ExtractContents(furnace.GetSlotValue(furnace.ResultSlotIndex))==CookedMeatBlock.Index&&furnace.GetSlotCount(0)==0&&furnace.GetSlotCount(furnace.FuelSlotIndex)==0&&Count(PlanksBlock.Index)==3,"native cooking conservation failed");Log("native_cooked_product",new{slots=Slots(furnace),seconds=elapsed-started});int empty=Enumerable.Range(0,Inventory.SlotsCount).First(i=>Inventory.GetSlotCount(i)==0);Transfer(furnace,furnace.ResultSlotIndex,Inventory,empty);stage=16;}
  else if(stage==16&&ActionDone()){Require(Count(CookedMeatBlock.Index)==1,"cooked meat not carried");foodBefore=p.ComponentVitalStats.Food;eatenBefore=p.PlayerStats.FoodItemsEaten;int slot=Slot(CookedMeatBlock.Index);run=actions.Start(new Eat(slot,Inventory.GetSlotValue(slot),1));stage=17;}
  else if(stage==17&&ActionDone()){Require(Count(CookedMeatBlock.Index)==0&&Count(RawMeatBlock.Index)==0&&Count(PlanksBlock.Index)==3&&p.ComponentVitalStats.Food>foodBefore&&p.PlayerStats.FoodItemsEaten==eatenBefore+1,"native meal accounting failed");Log("final_inventory_before_assertions",new{inventory=Slots(Inventory),baseline});Require(baseline.All(k=>Enumerable.Range(0,Inventory.SlotsCount).Where(i=>Inventory.GetSlotValue(i)==k.Key||(Terrain.ExtractContents(k.Key)==CookedFishBlock.Index&&BlocksManager.Blocks[CookedFishBlock.Index].GetDamage(k.Key)==0&&Inventory.GetSlotValue(i)==BlocksManager.Blocks[CookedFishBlock.Index].SetDamage(k.Key,1))).Sum(Inventory.GetSlotCount)==k.Value),"baseline changed beyond native cooked-fish aging 0->1");Require(Enumerable.Range(0,Inventory.SlotsCount).Sum(Inventory.GetSlotCount)==baseline.Values.Sum()+3,"unexpected total inventory");var own=p.Entity.FindComponent<ComponentCraftingTable>(true);var tableInv=p.Project.FindSubsystem<SubsystemBlockEntities>(true).GetBlockEntity(table).Entity.FindComponent<ComponentCraftingTable>(true);Require(new IInventory[]{own,tableInv,furnace}.All(inv=>Enumerable.Range(0,inv.SlotsCount).All(i=>inv.GetSlotCount(i)==0)),"workspace residuals");Log("cooking_meal_verified",new{foodBefore,foodAfter=p.ComponentVitalStats.Food,inventory=Slots(Inventory),own=Slots(own),table=Slots(tableInv),furnace=Slots(furnace),health=p.ComponentHealth.Health});Done=true;}
 }
 public void Dispose(){if(disposed)return;disposed=true;try{Call("cancel_task");Call("cancel_action");if(run?.Result.Status==AtomicActionStatus.Running)actions.Cancel(run);}finally{var u=p.Project.FindSubsystem<SubsystemUpdate>(true);u.RemoveUpdateable(this);u.RemoveUpdateable(senses);senses.Dispose();interests.Release();backend.Dispose();}}
}
